import { TextArea } from '@/lib/designsystem';

// Basic usage
<TextArea
  id="description"
  label="Description"
  placeholder="Enter a detailed description"
  onChange={(e) => setDescription(e.target.value)}
  value={description}
  rows={4}
/>

// With error state
<TextArea
  id="bio"
  label="Biography"
  error="Biography is required"
  touched={true}
  value={bio}
  onChange={(e) => setBio(e.target.value)}
  rows={6}
/>

// With helper text
<TextArea
  id="feedback"
  label="Feedback"
  helperText="Please provide detailed feedback to help us improve"
  required
  value={feedback}
  onChange={(e) => setFeedback(e.target.value)}
/>

// Compact mode for sidebars/dense UIs
<TextArea
  id="prompt"
  label="Your Prompt"
  value={prompt}
  onChange={(e) => setPrompt(e.target.value)}
  helperText="Enter a brief description"
  rows={3}
  compact
/>

import { useState } from 'react';
import { TextArea, Button } from '@/lib/designsystem';

function FeedbackForm() {
  const [feedback, setFeedback] = useState('');
  const [error, setError] = useState('');
  const [touched, setTouched] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!feedback.trim()) {
      setError('Feedback is required');
      return;
    }

    // Submit form
    console.log('Feedback submitted:', feedback);
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <TextArea
        id="feedback"
        label="Your Feedback"
        placeholder="Please share your thoughts..."
        value={feedback}
        onChange={(e) => setFeedback(e.target.value)}
        onBlur={() => setTouched(true)}
        error={error}
        touched={touched}
        helperText="Your feedback helps us improve our service"
        required
        rows={5}
      />

      <Button type="submit">Submit Feedback</Button>
    </form>
  );
}
